ALTER TABLE "booklet_remito" ADD COLUMN "modo" text DEFAULT 'cabecera' NOT NULL;--> statement-breakpoint
ALTER TABLE "booklet_remito" ADD CONSTRAINT "booklet_remito_modo_check" CHECK ("booklet_remito"."modo" IN ('cabecera', 'directo') AND (("booklet_remito"."modo" = 'cabecera' AND "booklet_remito"."cabecera_cue_anexo" IS NOT NULL) OR ("booklet_remito"."modo" = 'directo' AND "booklet_remito"."cabecera_cue_anexo" IS NULL)));--> statement-breakpoint
ALTER TABLE "booklet_remito" ADD CONSTRAINT "booklet_remito_receipt_signature_check" CHECK (("booklet_remito"."modo" = 'cabecera' AND (("booklet_remito"."status" = 'received' AND "booklet_remito"."cabecera_received_by_user_id" IS NOT NULL AND "booklet_remito"."cabecera_received_at" IS NOT NULL) OR ("booklet_remito"."status" = 'dispatched' AND "booklet_remito"."cabecera_received_by_user_id" IS NULL AND "booklet_remito"."cabecera_received_at" IS NULL))) OR ("booklet_remito"."modo" = 'directo' AND "booklet_remito"."cabecera_received_by_user_id" IS NULL AND "booklet_remito"."cabecera_received_at" IS NULL));--> statement-breakpoint
ALTER TABLE "booklet_remito_item" ADD CONSTRAINT "booklet_remito_item_school_check" CHECK ("booklet_remito_item"."school_received_quantity" IS NULL OR ("booklet_remito_item"."school_received_quantity" >= 0 AND "booklet_remito_item"."school_received_quantity" <= COALESCE("booklet_remito_item"."cabecera_received_quantity", "booklet_remito_item"."dispatched_quantity")));